from hermes_tools import terminal
script = r'''python3 - <<'PY'
import sqlite3,re,math
c=sqlite3.connect('hermes/state.db')
text=c.execute("SELECT content FROM messages WHERE session_id=? AND role='user' AND content LIKE '%Demo pair 1 input%' ORDER BY id LIMIT 1",('fc24cff0-0ed2-4868-9e7e-65191d28d400',)).fetchone()[0]
def parse(n,kind):
 pat=r'Demo pair '+str(n)+' '+kind+r' \(\d+x\d+\):\n(.*?)(?=\n(?:Demo pair|Same instance|$))'
 m=re.search(pat,text,re.S)
 return [list(map(int,re.findall(r'\d+',line))) for line in m.group(1).strip().splitlines()]
def axis_fill(g,marker,color):
 o=[r[:] for r in g]
 for r in range(len(g)):
  xs=[j for j,v in enumerate(g[r]) if v==marker]
  for a,b in zip(xs,xs[1:]):
   for j in range(a+1,b):o[r][j]=color
 for j in range(len(g[0])):
  xs=[i for i in range(len(g)) if g[i][j]==marker]
  for a,b in zip(xs,xs[1:]):
   for i in range(a+1,b):o[i][j]=color
 return o
for n,m in [(1,9),(2,4)]:
 a,b=parse(n,'input'),parse(n,'output')
 print('demo',n,'axis rule exact:',axis_fill(a,m,3)==b,'dimensions:',len(a),len(a[0]))
T=[[8]*8 for _ in range(30)]
for r,j in [(2,7),(4,8),(6,1),(6,8),(10,3),(13,3),(13,5),(18,7),(21,8),(22,6)]:T[r-1][j-1]=7
O=axis_fill(T,7,3)
print('test output:')
for row in O:print(' '.join(map(str,row)))
g=parse(1,'input'); markers=[(i,j) for i,row in enumerate(g) for j,v in enumerate(row) if v==9]
pts=set()
for k,(r1,c1) in enumerate(markers):
 for r2,c2 in markers[k+1:]:
  dr,dc=r2-r1,c2-c1; d=math.gcd(abs(dr),abs(dc))
  for t in range(1,d):pts.add((r1+t*dr//d,c1+t*dc//d))
observed={(i,j) for i,row in enumerate(parse(1,'output')) for j,v in enumerate(row) if v==3}
extra=pts-observed
print('general straight-lattice candidate unsupported extra count:',len(extra),'examples (1-based):',sorted((r+1,c+1) for r,c in extra)[:8])
PY'''
